/** Root of a tree: a leaf carries `value`, a folder carries `children`, never both. */
export type Data = { name: string; value?: number; children?: Data[] };

type Cell = d3.HierarchyRectangularNode<Data>;
/** Where a cell sits under some frame of reference, in pixels. */
type Box = { x: number; y: number; w: number; h: number };

const HEADER = 26;
const FONT_SIZE = 11;
/** Mean advance width of 11px sans-serif; labels wider than their cell are never created. */
const CHAR_WIDTH = 6.2;
const TRANSITION = { duration: 0.75, ease: 'easeInOut' } as const;
const INK_ON_LIGHT = '#16202c';
const INK_ON_DARK = '#f2f5f8';

const format = d3.format(',d');
const trail = (d: Cell) => d.ancestors().reverse().map((n) => n.data.name).join(' / ');

export default function ZoomableTreemap({
  data = sourceTree,
  width
}: {
  data?: Data;
  width: number;
}) {
  // Hooks run before the width===0 guard below, and d3.treemap throws on a zero-sized layout.
  const side = Math.max(width, 1);
  const height = Math.round(side * 0.6);

  // The descent as names rather than as nodes, so it survives `root` being rebuilt on resize.
  const [path, setPath] = useState<string[]>([]);

  const root = useMemo(() => {
    // Binary tiling is re-run against the full frame, so a zoomed cell is laid out for
    // the aspect ratio it will actually fill rather than for its slot in the parent.
    const tile = (node: Cell, x0: number, y0: number, x1: number, y1: number) => {
      d3.treemapBinary(node, 0, 0, side, height);
      for (const child of node.children ?? []) {
        child.x0 = x0 + (child.x0 / side) * (x1 - x0);
        child.x1 = x0 + (child.x1 / side) * (x1 - x0);
        child.y0 = y0 + (child.y0 / height) * (y1 - y0);
        child.y1 = y0 + (child.y1 / height) * (y1 - y0);
      }
    };
    return d3
      .treemap<Data>()
      .tile(tile)
      .size([side, height])(
        d3
          .hierarchy(data)
          .sum((d) => d.value ?? 0)
          .sort((a, b) => (b.value ?? 0) - (a.value ?? 0))
      );
  }, [data, side, height]);

  const focus = useMemo(() => {
    let node = root;
    for (const name of path) {
      const next = node.children?.find((child) => child.data.name === name);
      if (!next) break;
      node = next;
    }
    return node;
  }, [root, path]);

  const color = useMemo(
    () =>
      d3
        .scaleOrdinal(d3.schemeObservable10)
        .domain((root.children ?? []).map((d) => d.data.name)),
    [root]
  );

  // The frame the previous render drew under. Entering cells start from where they sat in it,
  // which is what makes the descent read as a zoom rather than as a cut. Written in an effect
  // so it still holds the old frame while the render that changed the focus is in progress.
  const previous = useRef(focus);
  useEffect(() => {
    previous.current = focus;
  });

  if (width === 0) return null;

  /** A cell's box relative to whichever ancestor is filling the frame. */
  const boxOf = (frame: Cell, d: Cell): Box => {
    if (d === frame) return { x: 0, y: -HEADER, w: side, h: HEADER };
    const kx = side / Math.max(1e-9, frame.x1 - frame.x0);
    const ky = height / Math.max(1e-9, frame.y1 - frame.y0);
    return {
      x: (d.x0 - frame.x0) * kx,
      y: (d.y0 - frame.y0) * ky,
      w: (d.x1 - d.x0) * kx,
      h: (d.y1 - d.y0) * ky
    };
  };

  const branch = (d: Cell) => d.ancestors().find((n) => n.depth === 1)?.data.name ?? '';
  const fill = (d: Cell) => {
    if (d === focus) return 'var(--line)';
    const base = color(branch(d));
    return d.children ? d3.color(base)?.darker(0.7).formatHex() ?? base : base;
  };
  const ink = (d: Cell) =>
    d === focus ? 'var(--text)' : d.children ? INK_ON_DARK : INK_ON_LIGHT;

  const cells = [...(focus.children ?? []), focus];

  return (
    <svg
      viewBox={`0 ${-HEADER} ${side} ${height + HEADER}`}
      width="100%"
      height={height + HEADER}
      role="img"
      aria-label="Zoomable treemap of a monorepo's source lines; click a cell to descend, the header to go back"
      style={{ display: 'block' }}
    >
      {cells.map((d) => {
        const box = boxOf(focus, d);
        // Where this cell sat in the frame we are leaving. A cell that existed there keeps its
        // key and tweens; a cell that did not mounts at that spot and expands out of it, which
        // is the whole zoom cue. On the first render the two frames are the same, so nothing
        // moves and a server render draws the finished picture.
        const from = d === focus ? box : boxOf(previous.current, d);
        const clickable = d === focus ? d.parent !== null : d.children !== undefined;
        const name = d === focus ? trail(d) : d.data.name;
        const value = format(d.value ?? 0);
        const fitsName = box.w >= name.length * CHAR_WIDTH + 10 && box.h >= FONT_SIZE + 6;
        const fitsValue = fitsName && box.h >= 2.6 * FONT_SIZE + 6;

        return (
          <motion.g
            key={trail(d)}
            initial={{ x: from.x, y: from.y }}
            animate={{ x: box.x, y: box.y }}
            transition={TRANSITION}
            cursor={clickable ? 'pointer' : undefined}
            onClick={() => {
              if (!clickable) return;
              setPath(d === focus ? path.slice(0, -1) : [...path, d.data.name]);
            }}
          >
            <title>{`${trail(d)}\n${value} lines`}</title>
            <motion.rect
              initial={{ width: from.w, height: from.h }}
              animate={{ width: box.w, height: box.h }}
              transition={TRANSITION}
              fill={fill(d)}
              stroke="var(--bg)"
            />
            {fitsName && (
              <text fontSize={FONT_SIZE} fill={ink(d)} pointerEvents="none">
                <tspan x={5} y="1.2em" fontWeight={d === focus ? 600 : 400}>
                  {name}
                </tspan>
                {fitsValue && (
                  <tspan x={5} y="2.5em" fillOpacity={0.75}>
                    {value}
                  </tspan>
                )}
              </text>
            )}
          </motion.g>
        );
      })}
    </svg>
  );
}
